defmodule Mix.Tasks.Roux.Gen.Zed do
  @moduledoc """
  Generates a Zed editor extension for Roux-powered languages.

  Takes language module names as positional arguments and generates the
  extension manifest, per-language TOML configs, and copies the pre-built
  `extension.wasm` from roux's `priv/` directory.

  ## Usage

      mix roux.gen.zed Lark OtherLang
      mix roux.gen.zed Lark --output path/to/zed

  ## Generated files

      <output>/
        extension.toml              # extension manifest listing all languages
        extension.wasm              # pre-built WASM binary (copied from roux)
        languages/<name>/config.toml  # one per language

  ## Options

    * `--output` - output directory (default: `editors/zed/`)
  """

  @shortdoc "Generates a Zed extension for Roux languages"

  use Mix.Task

  @default_output "editors/zed"

  @impl true
  def run(argv) do
    {opts, args} = OptionParser.parse!(argv, strict: [output: :string])
    output = Keyword.get(opts, :output, @default_output)

    if args == [] do
      Mix.shell().info("warning: no language modules specified, generating extension shell only")
    end

    Mix.Task.run("compile")

    lang_modules = Enum.map(args, &resolve_module/1)
    Enum.each(lang_modules, &validate_lang!/1)

    project = Mix.Project.config()
    app_name = Atom.to_string(project[:app])

    File.mkdir_p!(output)

    generated = []

    # Generate extension.toml.
    extension_path = Path.join(output, "extension.toml")
    extension_content = gen_extension_toml(app_name, lang_modules)
    File.write!(extension_path, extension_content)
    generated = [extension_path | generated]

    # Generate per-language config.toml files.
    lang_paths =
      Enum.map(lang_modules, fn lang ->
        name = Roux.Lang.language_name(lang)
        dir_name = String.downcase(name)
        lang_dir = Path.join([output, "languages", dir_name])
        File.mkdir_p!(lang_dir)

        config_path = Path.join(lang_dir, "config.toml")
        config_content = gen_language_toml(lang)
        File.write!(config_path, config_content)

        config_path
      end)

    generated = Enum.reverse(lang_paths) ++ generated

    # Copy extension.wasm from roux's priv/.
    wasm_source = wasm_path()
    wasm_dest = Path.join(output, "extension.wasm")

    if File.exists?(wasm_source) do
      File.cp!(wasm_source, wasm_dest)
      generated = [wasm_dest | generated]

      Mix.shell().info("Generated Zed extension in #{output}/:")

      Enum.each(Enum.reverse(generated), fn path ->
        Mix.shell().info("  #{path}")
      end)
    else
      Mix.shell().info("Generated Zed extension in #{output}/:")

      Enum.each(Enum.reverse(generated), fn path ->
        Mix.shell().info("  #{path}")
      end)

      Mix.shell().info("warning: extension.wasm not found at #{wasm_source} — copy it manually")
    end

    :ok
  end

  @doc false
  def gen_extension_toml(app_name, lang_modules) do
    display_name =
      app_name
      |> String.split("_")
      |> Enum.map_join(" ", &String.capitalize/1)

    language_names =
      lang_modules
      |> Enum.map(&Roux.Lang.language_name/1)
      |> Enum.map(&inspect/1)
      |> Enum.join(", ")

    """
    # Generated by mix roux.gen.zed — do not edit manually.

    id = "#{app_name}-lsp"
    name = "#{display_name} LSP"
    description = "Language server for #{display_name} (powered by Roux)"
    version = "0.1.0"
    schema_version = 1
    authors = []
    repository = ""

    [language_servers.roux-lsp]
    name = "Roux LSP"
    languages = [#{language_names}]
    """
  end

  @doc false
  def gen_language_toml(lang_module) do
    name = Roux.Lang.language_name(lang_module)

    suffixes =
      lang_module.file_extensions()
      |> Enum.map(fn ext -> String.trim_leading(ext, ".") end)
      |> Enum.map(&inspect/1)
      |> Enum.join(", ")

    comments =
      lang_module
      |> Roux.Lang.line_comments()
      |> Enum.map(&inspect/1)
      |> Enum.join(", ")

    """
    # Generated by mix roux.gen.zed — do not edit manually.

    name = "#{name}"
    path_suffixes = [#{suffixes}]
    line_comments = [#{comments}]
    """
  end

  defp resolve_module(name) do
    # Accept both "Lark" and "Elixir.Lark" forms.
    Module.concat([name])
  end

  defp validate_lang!(module) do
    unless Code.ensure_loaded?(module) do
      Mix.raise("could not load module #{inspect(module)} — is it compiled?")
    end

    unless function_exported?(module, :file_extensions, 0) do
      Mix.raise("#{inspect(module)} does not implement the Roux.Lang behaviour")
    end
  end

  defp wasm_path do
    roux_priv = :code.priv_dir(:roux)

    case roux_priv do
      {:error, :bad_name} ->
        # Fallback for development: look relative to this file's app.
        Path.join([File.cwd!(), "priv", "editors", "zed", "extension.wasm"])

      path when is_list(path) ->
        Path.join([List.to_string(path), "editors", "zed", "extension.wasm"])
    end
  end
end
